class APICache{constructor(ttl=60000){this.cache=new Map();this.ttl=ttl;}
generateKey(endpoint,params){return`${endpoint}:${JSON.stringify(params)}`;}
get(endpoint,params){const key=this.generateKey(endpoint,params);const cached=this.cache.get(key);if(cached&&Date.now()-cached.timestamp<this.ttl){return cached.data;}
this.cache.delete(key);return null;}
set(endpoint,params,data){const key=this.generateKey(endpoint,params);this.cache.set(key,{data,timestamp:Date.now()});}
invalidate(endpoint){for(const key of this.cache.keys()){if(key.startsWith(endpoint+':')){this.cache.delete(key);}}}
clear(){this.cache.clear();}
getSize(){return this.cache.size;}}
const staticDataCache=new APICache(3600000);const parseCache=new APICache(300000);const testCache=new APICache(60000);const API={_cache:{static:staticDataCache,parse:parseCache,test:testCache},async makeCall(endpoint,data){try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',},body:JSON.stringify(data)});if(!response.ok){const errorData=await response.json();throw new Error(errorData.message||`HTTP ${response.status}`);}
const result=await response.json();if(result.error){throw new Error(result.message||'API returned an error');}
return result;}catch(error){console.error(`API call to ${endpoint} failed:`,error);throw error;}},async parseRule(rule,version){const cached=parseCache.get('/api/parse',{rule,version});if(cached){return cached;}
const result=await this.makeCall('/api/parse',{rule,version});parseCache.set('/api/parse',{rule,version},result);return result;},async testCommand(rule,command,version){const cached=testCache.get('/api/test-command',{rule,command,version});if(cached){return cached;}
const result=await this.makeCall('/api/test-command',{rule,command,version});testCache.set('/api/test-command',{rule,command,version},result);return result;},async validateRule(rule,version){return this.makeCall('/api/validate-rule',{rule,version});},async analyzeRedundancy(rule,version){return this.makeCall('/api/analyze-redundancy',{rule,version});},async optimizeRule(rule,version){return this.makeCall('/api/optimize-rule',{rule,version});},async searchCommands(pattern,version,limit=50){return this.makeCall('/api/search-commands',{pattern,version,limit});},async getCommandInfo(command,version){return this.makeCall('/api/command-info',{command,version});},async getCategories(version){const cached=staticDataCache.get('/api/categories',{version});if(cached){return cached;}
try{const response=await fetch(`/api/categories?version=${version}`);if(!response.ok){throw new Error(`HTTP ${response.status}`);}
const result=await response.json();if(result.error){throw new Error(result.message||'API returned an error');}
staticDataCache.set('/api/categories',{version},result);return result;}catch(error){console.error('API call to /api/categories failed:',error);throw error;}},async getAllCommands(version){const cached=staticDataCache.get('/api/allcommands',{version});if(cached){return cached;}
const fullRuleResponse=await this.parseRule('+@all',version);if(fullRuleResponse&&fullRuleResponse.grouped_commands){const allCommands=new Set();Object.values(fullRuleResponse.grouped_commands).forEach(commands=>{commands.forEach(cmd=>allCommands.add(cmd));});const result=Array.from(allCommands).sort();staticDataCache.set('/api/allcommands',{version},result);return result;}
return[];},async testCommandKey(rule,command,key,version){const cached=testCache.get('/api/test-command-key',{rule,command,key,version});if(cached){return cached;}
const result=await this.makeCall('/api/test-command-key',{rule,command,key,version});testCache.set('/api/test-command-key',{rule,command,key,version},result);return result;},invalidateCaches(){parseCache.clear();testCache.clear();}};export default API;